344	/// 对象标识符（OID），以各段弧的数值保存，用于向调用方展示实际标识。
345	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
346	pub struct ObjectIdentifier(Vec<u64>);
347	
348	impl ObjectIdentifier {
349	    /// 返回各段弧的数值，例如 Ed25519 为 `[1, 3, 101, 112]`。
350	    pub fn arcs(&self) -> &[u64] {
351	        &self.0
352	    }
353	}
354	
355	impl fmt::Display for ObjectIdentifier {
356	    /// 点分十进制写法，例如 `1.3.101.112`。
357	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
358	        let mut arcs = self.0.iter();
359	        if let Some(first) = arcs.next() {
360	            write!(f, "{first}")?;
361	            for arc in arcs {
362	                write!(f, ".{arc}")?;
363	            }
364	        }
365	        Ok(())
366	    }
367	}
368	
369	/// 导入 Ed25519 公钥失败时返回的类型化错误。
370	///
371	/// 调用方按变体即可区分两类失败，无需分析提示字符串：编码或公钥结构
372	/// 不合法是 [`Malformed`](Self::Malformed)；结构完整、DER 合法但算法
373	/// 标识不是 Ed25519 是 [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)。
374	/// 任何失败都不会产出可继续使用的公钥对象。
375	#[derive(Debug, Clone, PartialEq, Eq)]
376	pub enum ImportPublicKeyError {
377	    /// 输入不是一份完整、规范的 DER 编码 SubjectPublicKeyInfo：截断、
378	    /// 声明长度与实际内容不符、非规范长度编码、算法参数未缺省（含写成
379	    /// NULL）、位串未使用位数非零、容器中出现多余字段或对象之后还有
380	    /// 字节等；当算法标识确为 Ed25519（`1.3.101.112`）时，公钥长度不是
381	    /// 32 字节也属于本变体。注意：其他算法容器里的公钥长度（例如
382	    /// Ed448 的 57 字节）不作为格式问题——那属于
383	    /// [`UnsupportedAlgorithm`](Self::UnsupportedAlgorithm)。
384	    /// 走 PEM 入口（`from_spki_pem`）时，PEM 外壳的损坏（标签缺失或不
385	    /// 是 `PUBLIC KEY`、首尾之外有多余内容、正文空行或行内空白、Base64
386	    /// 非法字符或填充不规范等）也统一归为本变体。
387	    Malformed,
