415	/// 读取一个 DER TLV，返回（标签，内容，剩余字节）。
416	///
417	/// 只接受规范（最短）定长编码：拒绝不定长形式、长形式的前导零字节，
418	/// 以及本可以用短形式表示的长度；声明长度超出实际剩余内容同样失败。
419	/// 本模块只使用单字节通用标签，多字节标签形式一律拒绝。
420	fn read_der_tlv(data: &[u8]) -> Option<(u8, &[u8], &[u8])> {
421	    let (&tag, rest) = data.split_first()?;
422	    if tag & 0x1f == 0x1f {
423	        return None;
424	    }
425	    let (&first_len, rest) = rest.split_first()?;
426	    let (len, rest) = if first_len & 0x80 == 0 {
427	        (first_len as usize, rest)
428	    } else {
429	        let n = (first_len & 0x7f) as usize;
430	        // 0x80 是不定长形式，DER 不允许；长度本身也不允许超过 8 字节。
431	        if n == 0 || n > 8 || rest.len() < n {
432	            return None;
433	        }
434	        let (len_bytes, rest) = rest.split_at(n);
435	        // 前导零字节是非规范编码。
436	        if len_bytes[0] == 0 {
437	            return None;
438	        }
439	        let mut value: u64 = 0;
440	        for &b in len_bytes {
441	            value = (value << 8) | u64::from(b);
442	        }
443	        // 能用短形式表示的长度却用了长形式，同样是非规范编码。
444	        if value < 128 {
445	            return None;
446	        }
447	        (usize::try_from(value).ok()?, rest)
448	    };
449	    if rest.len() < len {
450	        return None;
451	    }
452	    let (content, rest) = rest.split_at(len);
453	    Some((tag, content, rest))
454	}
