456	/// 把 OID 的 DER 内容字节解码为各段弧的数值。
457	///
458	/// 只接受规范编码：内容非空，每个子标识符按最短形式编码（不允许
459	/// 前导的 0x80 字节），最后一个子标识符必须完整结束。各段弧以 u64
460	/// 保存，因此每段数值都必须落在 u64 范围内；第一个子标识符合并编码
461	/// 前两段弧（首段为 2 时合并值为 80 + 第二段），最大可到
462	/// `u64::MAX + 80`，超出该上界的合并值或超出 u64 的后续各段都属于
463	/// 编码损坏，不得截断、回绕或改写成别的数值。
464	fn decode_oid(content: &[u8]) -> Option<ObjectIdentifier> {
465	    // 合法子标识符的最大值：首段为 2、第二段为 u64::MAX 时，合并编码的
466	    // 第一个子标识符为 u64::MAX + 80。子标识符的数值在编码过程中只会
467	    // 增大，一旦超过该上界就不可能再对应任何可表示的弧，可立即判定
468	    // 编码损坏；累加器因此始终远小于 u128::MAX，移位不会溢出。
469	    const MAX_SUBIDENTIFIER: u128 = u64::MAX as u128 + 80;
470	
471	    if content.is_empty() {
472	        return None;
473	    }
474	    let mut subidentifiers: Vec<u128> = Vec::new();
475	    let mut value: u128 = 0;
476	    let mut in_arc = false;
477	    for &b in content {
478	        if !in_arc {
479	            // 子标识符首字节为 0x80 是前导零的非规范编码。
480	            if b == 0x80 {
481	                return None;
482	            }
483	            in_arc = true;
484	        }
485	        value = (value << 7) | u128::from(b & 0x7f);
486	        if value > MAX_SUBIDENTIFIER {
487	            return None;
488	        }
489	        if b & 0x80 == 0 {
490	            subidentifiers.push(value);
491	            value = 0;
492	            in_arc = false;
493	        }
494	    }
495	    // 最后一个子标识符的续位未结束：内容被截断。
496	    if in_arc {
497	        return None;
498	    }
499	    let (&first, rest) = subidentifiers.split_first()?;
500	    // 第一个子标识符合并编码前两段弧：0..=39 → 0.x，40..=79 → 1.x，
501	    // 其余 → 2.x。首段为 2 时第二段可以接近 u64::MAX，合并值因此
502	    // 可能超过 u64，必须先按 u128 拆开再逐段检查范围。
503	    let (arc0, arc1) = if first < 40 {
504	        (0, first)
505	    } else if first < 80 {
506	        (1, first - 40)
507	    } else {
508	        (2, first - 80)
509	    };
510	    let mut arcs = Vec::with_capacity(rest.len() + 2);
511	    arcs.push(u64::try_from(arc0).ok()?);
512	    arcs.push(u64::try_from(arc1).ok()?);
513	    for &arc in rest {
514	        // 后续每段都必须落在 u64 范围内，超出即编码损坏。
515	        arcs.push(u64::try_from(arc).ok()?);
516	    }
517	    Some(ObjectIdentifier(arcs))
518	}
