520	const PEM_BEGIN: &[u8] = b"-----BEGIN PUBLIC KEY-----";
521	const PEM_END: &[u8] = b"-----END PUBLIC KEY-----";
522	
523	/// 解析一份严格的 PEM `PUBLIC KEY` 块，返回还原出的 DER 字节。
524	///
525	/// 接受的完整形态只有：
526	///
527	/// ```text
528	/// -----BEGIN PUBLIC KEY-----<LF|CRLF>
529	/// <标准 Base64 正文，一行或多行，以 LF|CRLF 结束>
530	/// -----END PUBLIC KEY-----[无换行|LF|CRLF]
531	/// ```
532	///
533	/// 首标记必须从输入第一个字节开始，且之后紧跟一个行结束；正文由零或
534	/// 多行组成，每行只含 Base64 字符并以 LF/CRLF 结束，紧接着就是独占一行
535	/// 的尾标记（正文为空时拼接出的 Base64 串为空，交给解码器判错）；尾标记
536	/// 之后允许没有换行，或恰好一个 LF/CRLF。任何偏离（首尾之外有字节、
537	/// 其他标签、空行、行内空格或制表符、CR 单独成行、第二个块等）都是
538	/// 格式错误。这里不做任何裁剪，也不扫描或猜测“块可能在输入中间”。
539	fn parse_public_key_pem(input: &[u8]) -> Result<Vec<u8>, ImportPublicKeyError> {
540	    const MALFORMED: ImportPublicKeyError = ImportPublicKeyError::Malformed;
541	
542	    // 首标记从第一个字节开始，占满一行：前面不允许有任何内容。
543	    let rest = input.strip_prefix(PEM_BEGIN).ok_or(MALFORMED)?;
544	    let rest = strip_line_ending(rest).ok_or(MALFORMED)?;
545	
546	    // 逐行消费正文：每一非尾行都必须以 LF/CRLF 结束；遇到尾标记行时
547	    // 正文结束。先确认尾标记独占一行（它前面必须是上面接受的那个行
548	    // 结束），因此空行、行内空白、夹在正文行中的尾标记文字等都无法
549	    // 混入。行内只允许 Base64 字符与填充符 `=`；填充在整体串中的位置、
550	    // 数量是否规范，拼回完整串后交由解码器统一判定（包括跨行情形）。
551	    let mut b64 = Vec::new();
552	    let mut cursor = rest;
553	    let after_end = loop {
554	        if let Some(after) = cursor.strip_prefix(PEM_END) {
555	            break after;
556	        }
557	        let line_end = find_line_ending(cursor).ok_or(MALFORMED)?;
558	        let (line, after) = cursor.split_at(line_end);
559	        // 空行（相邻两个行结束）、行内空格或制表符、连字符等任何其他
560	        // 字节都不接受；`=` 先放行，规范性在解码时判定。
561	        if line.is_empty() || !line.iter().all(|&b| is_b64_char(b) || b == b'=') {
562	            return Err(MALFORMED);
563	        }
564	        b64.extend_from_slice(line);
565	        // 跳过这一个行结束（LF 或 CRLF），继续下一行。
566	        cursor = &after[if after.first() == Some(&b'\r') { 2 } else { 1 }..];
567	    };
568	
569	    // 尾标记之后允许没有换行，或只有一个 LF/CRLF；除此之外一律拒绝，
570	    // 包括第二个块、额外空行与杂散字节。
571	    if !after_end.is_empty() && after_end != b"\n" && after_end != b"\r\n" {
572	        return Err(MALFORMED);
573	    }
574	
575	    decode_standard_base64(&b64).ok_or(MALFORMED)
576	}
577	
578	/// 若 `data` 以 LF 或 CRLF 开头，返回行结束之后的字节，否则返回 `None`。
579	fn strip_line_ending(data: &[u8]) -> Option<&[u8]> {
580	    match data.first()? {
581	        b'\n' => Some(&data[1..]),
582	        b'\r' if data.get(1) == Some(&b'\n') => Some(&data[2..]),
583	        _ => None,
584	    }
585	}
586	
587	/// 返回 `data` 中第一个 LF 的位置；它前面紧邻 CR 时该位置仍是 CRLF 的
588	/// 结束边界。单独的 CR 找不到 LF，因此不被当作行结束——这与
589	/// [`strip_line_ending`] 只接受 LF/CRLF 的规则一致。
590	fn find_line_ending(data: &[u8]) -> Option<usize> {
591	    data.iter().position(|&b| b == b'\n').map(|lf| {
592	        if lf > 0 && data[lf - 1] == b'\r' {
593	            lf - 1
594	        } else {
595	            lf
596	        }
597	    })
598	}
