600	/// 标准 Base64 字母表（RFC 4648 第 4 节），不含 URL 安全变体与任何空白。
601	fn is_b64_char(b: u8) -> bool {
602	    matches!(b, b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'+' | b'/')
603	}
604	
605	/// 严格解码标准 Base64（含填充）。
606	///
607	/// 只接受 RFC 4648 标准字母表与规范填充：
608	/// - 非法字符（含 URL 安全字母 `-`、`_`、空白、换行）一律拒绝；
609	/// - 长度必须是 4 的倍数，且只有最后一个四元组允许填充；
610	/// - `=` 只能连续出现在末尾：缺填充、多填充、填充后仍有编码字符都拒绝；
611	/// - 末尾量子的未使用位必须全部为零（非规范的 `AB!=` 式编码被拒绝）。
612	///
613	/// 解码结果以 `Vec<u8>` 返回，长度由四元组数决定，任何阶段出错都返回
614	/// `None`，不返回部分结果。
615	fn decode_standard_base64(input: &[u8]) -> Option<Vec<u8>> {
616	    if input.is_empty() || input.len() % 4 != 0 {
617	        return None;
618	    }
619	
620	    let group_count = input.len() / 4;
621	    let mut out = Vec::with_capacity(group_count * 3);
622	    for (i, chunk) in input.chunks_exact(4).enumerate() {
623	        let is_last = i + 1 == group_count;
624	        if !is_last {
625	            // 填充只允许出现在最后一个四元组：前面的组里出现 `=` 即非法。
626	            if chunk.iter().any(|&b| b == b'=') {
627	                return None;
628	            }
629	            let v = decode_quartet(chunk)?;
630	            out.push((v >> 16) as u8);
631	            out.push((v >> 8) as u8);
632	            out.push(v as u8);
633	            continue;
634	        }
635	
636	        // 最后一组：识别 0/1/2 个填充，并检查末尾未使用位是否全为零。
637	        let (v, out_len) = match chunk {
638	            [a, b, c, d] if *d != b'=' && *c != b'=' => {
639	                (decode_quartet(&[*a, *b, *c, *d])?, 3usize)
640	            }
641	            [a, b, c, b'='] if *c != b'=' && *b != b'=' => {
642	                (decode_quartet(&[*a, *b, *c, b'A'])?, 2)
643	            }
644	            [a, b, b'=', b'='] if *b != b'=' => {
645	                (decode_quartet(&[*a, *b, b'A', b'A'])?, 1)
646	            }
647	            _ => return None,
648	        };
649	        // 单填充时第三个量子（低 8 位）未使用；双填充时第二、三个量子
650	        //（低 16 位）未使用——必须全部为零，否则编码的字节数有歧义。
651	        let unused_ok = match out_len {
652	            3 => true,
653	            2 => v & 0x0000_00ff == 0,
654	            _ => v & 0x0000_ffff == 0,
655	        };
656	        if !unused_ok {
657	            return None;
658	        }
659	        out.push((v >> 16) as u8);
660	        if out_len >= 2 {
661	            out.push((v >> 8) as u8);
662	        }
663	        if out_len == 3 {
664	            out.push(v as u8);
665	        }
666	    }
667	    Some(out)
668	}
