670	/// 把恰好 4 个标准 Base64 字符（填充已由调用方替换为 `A`）解码为合并的
671	/// 24 位数值；任一字符不在标准字母表内即返回 `None`。
672	fn decode_quartet(chunk: &[u8]) -> Option<u32> {
673	    let mut v = 0u32;
674	    for &b in chunk {
675	        let sextet = b64_value(b)?;
676	        v = (v << 6) | u32::from(sextet);
677	    }
678	    Some(v)
679	}
680	
681	/// 单个标准 Base64 字符对应的 6 位值；`=` 与其他任何字节都不是合法字符。
682	fn b64_value(b: u8) -> Option<u8> {
683	    match b {
684	        b'A'..=b'Z' => Some(b - b'A'),
685	        b'a'..=b'z' => Some(b - b'a' + 26),
686	        b'0'..=b'9' => Some(b - b'0' + 52),
687	        b'+' => Some(62),
688	        b'/' => Some(63),
689	        _ => None,
690	    }
691	}
