756	    impl Read for ChunkedReader<'_> {
757	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
758	            if self.pos == self.data.len() {
759	                return Ok(0);
760	            }
761	            let mut limit = buf.len();
762	            if !self.chunk_sizes.is_empty() {
763	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
764	                self.chunk_index += 1;
765	            }
766	            let n = limit.min(self.data.len() - self.pos);
767	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
768	            self.pos += n;
769	            Ok(n)
770	        }
771	    }
