824	    /// 按脚本驱动的读取器：每个步骤要么返回下一段内容（长度可短于缓冲区），
825	    /// 要么返回一个错误。脚本用完后继续返回剩余内容，内容耗尽后返回 Ok(0)。
826	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
827	    enum Step {
828	        /// 返回下一段内容（可为空切片以外的任意长度）。
829	        Data,
830	        /// 返回指定错误。
831	        Fail(io::ErrorKind, &'static str),
832	    }
833	
834	    struct ScriptedReader<'a> {
835	        data: &'a [u8],
836	        pos: usize,
837	        steps: &'a [Step],
838	        step_index: usize,
839	    }
840	
841	    impl<'a> ScriptedReader<'a> {
842	        fn new(data: &'a [u8], steps: &'a [Step]) -> Self {
843	            ScriptedReader { data, pos: 0, steps, step_index: 0 }
844	        }
845	    }
846	
847	    impl Read for ScriptedReader<'_> {
848	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
849	            match self.steps.get(self.step_index) {
850	                Some(Step::Data) => {
851	                    self.step_index += 1;
852	                    // 每段最多给剩余内容的一半，保证一段脚本可能对应多次内容返回，
853	                    // 且片段长度通常短于缓冲区容量。
854	                    let remaining = self.data.len() - self.pos;
855	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
856	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
857	                    self.pos += n;
858	                    Ok(n)
859	                }
860	                Some(Step::Fail(kind, msg)) => {
861	                    self.step_index += 1;
862	                    Err(io::Error::new(*kind, *msg))
863	                }
864	                None => {
865	                    let remaining = self.data.len() - self.pos;
866	                    let n = remaining.min(buf.len());
867	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
868	                    self.pos += n;
869	                    Ok(n)
870	                }
871	            }
872	        }
873	    }
