1238	    #[test]
1239	    fn imports_rfc8410_example_and_exposes_raw_bytes_and_hex() {
1240	        let key = Ed25519PublicKey::from_spki_der(RFC8410_SPKI).unwrap();
1241	
1242	        // 原始 32 字节就是位串里的公钥内容。
1243	        assert_eq!(key.as_bytes(), &RFC8410_SPKI[12..]);
1244	        // 文本表示是公钥本身的 64 个小写十六进制字符，不是公钥的 SHA-256 摘要。
