1585	    /// 把数值按 base-128 最短形式编码为一个 OID 子标识符，追加到 `out`。
1586	    /// 接受 u128 是为了能构造“合并前两段后超过 u64”的第一个子标识符。
1587	    fn push_subidentifier(out: &mut Vec<u8>, value: u128) {
1588	        let mut groups = [0u8; 19]; // u128 最多需要 ceil(128/7) = 19 组
1589	        let mut start = groups.len();
1590	        let mut v = value;
1591	        loop {
1592	            start -= 1;
1593	            groups[start] = (v & 0x7f) as u8;
1594	            v >>= 7;
1595	            if v == 0 {
1596	                break;
1597	            }
1598	        }
1599	        let end = groups.len() - 1;
1600	        for b in &mut groups[start..end] {
1601	            *b |= 0x80;
1602	        }
1603	        out.extend_from_slice(&groups[start..]);
1604	    }
1605	
1606	    /// 首段为 2 的 OID 内容字节：第一个子标识符合并编码 2*40 + arc1，
1607	    /// 其余各段依次跟在后面。
1608	    fn oid_content_starting_at_2(arc1: u64, rest: &[u64]) -> Vec<u8> {
1609	        let mut content = Vec::new();
1610	        push_subidentifier(&mut content, 80 + u128::from(arc1));
1611	        for &arc in rest {
1612	            push_subidentifier(&mut content, u128::from(arc));
1613	        }
1614	        content
1615	    }
