1661	        push_subidentifier(&mut content, u64::MAX as u128 + 81);
1662	        push_subidentifier(&mut content, 3);
1663	        let der = spki_der(&content, &[0x42; 32]);
1664	        assert_eq!(
1665	            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
1666	            ImportPublicKeyError::Malformed
1667	        );
1668	
1669	        // 大得多的合并值同样只是编码损坏，不能溢出或崩溃。
1670	        let mut content = Vec::new();
1671	        push_subidentifier(&mut content, u128::MAX);
1672	        let der = spki_der(&content, &[0x42; 32]);
1673	        assert_eq!(
1674	            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
1675	            ImportPublicKeyError::Malformed
1676	        );
1677	
1678	        // 后续段超出 u64（2.5.18446744073709551616）：同样报编码损坏。
1679	        let mut content = Vec::new();
1680	        push_subidentifier(&mut content, 85);
1681	        push_subidentifier(&mut content, u64::MAX as u128 + 1);
1682	        let der = spki_der(&content, &[0x42; 32]);
1683	        assert_eq!(
1684	            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
1685	            ImportPublicKeyError::Malformed
1686	        );
1687	
1688	        // 而后续段恰好为 u64::MAX（2.5.18446744073709551615）仍合法。
1689	        let mut content = Vec::new();
1690	        push_subidentifier(&mut content, 85);
1691	        push_subidentifier(&mut content, u64::MAX as u128);
1692	        let der = spki_der(&content, &[0x42; 32]);
1693	        match Ed25519PublicKey::from_spki_der(&der).unwrap_err() {
1694	            ImportPublicKeyError::UnsupportedAlgorithm(oid) => {
1695	                assert_eq!(oid.arcs(), &[2, 5, 18446744073709551615]);
1696	            }
1697	            other => panic!("expected UnsupportedAlgorithm, got {other:?}"),
1698	        }
1699	    }
1700	
1701	    #[test]
1702	    fn huge_arc_oid_still_enforces_strict_der() {
1703	        // 接近上限的标识不改变严格 DER 要求：能识别出其他算法，
1704	        // 也不能把编码损坏改报成算法不支持。
1705	        let valid = spki_der(&oid_content_starting_at_2(u64::MAX, &[3]), &[0x42; 32]);
1706	
1707	        // 冗余前导零：第一个子标识符前补一个 0x80 组。
1708	        let mut padded_content = vec![0x80];
1709	        padded_content.extend_from_slice(&oid_content_starting_at_2(u64::MAX, &[3]));
1710	        let der = spki_der(&padded_content, &[0x42; 32]);
1711	        assert_eq!(
1712	            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
1713	            ImportPublicKeyError::Malformed
1714	        );
