1835	    // 算法不是 Ed25519 → UnsupportedAlgorithm”与“编码损坏 → Malformed”
1836	    // 的区分不能改变。外层 SEQUENCE、算法标识所在 SEQUENCE、公钥位串三个
1837	    // 位置适用同一条规则。
1838	
1839	    /// 构造测试输入时某一层 TLV 长度字段的写法。
1840	    #[derive(Clone, Copy)]
1841	    enum LenStyle {
1842	        /// 规范最短形式：127 以内短形式，128 起最短长形式。
1843	        Canonical,
1844	        /// 长度小于 128 也写成长形式——本可用短形式，属于非规范编码。
1845	        ForcedLong,
1846	        /// 长形式数字前再补一个零字节——冗余前导零，属于非规范编码。
1847	        ForcedLongZeroPadded,
1848	    }
