1850	    /// 按指定风格生成一个 DER 长度字段的字节。
1851	    fn test_len_bytes(len: usize, style: LenStyle) -> Vec<u8> {
1852	        let mut base256 = Vec::new();
1853	        let mut v = len;
1854	        loop {
1855	            base256.push((v & 0xff) as u8);
1856	            v >>= 8;
1857	            if v == 0 {
1858	                break;
1859	            }
1860	        }
1861	        base256.reverse();
1862	        match style {
1863	            LenStyle::Canonical if len < 128 => vec![len as u8],
1864	            LenStyle::Canonical | LenStyle::ForcedLong => {
1865	                let mut out = vec![0x80 | base256.len() as u8];
1866	                out.extend_from_slice(&base256);
1867	                out
1868	            }
1869	            LenStyle::ForcedLongZeroPadded => {
1870	                let mut out = vec![0x80 | (base256.len() + 1) as u8, 0x00];
1871	                out.extend_from_slice(&base256);
1872	                out
1873	            }
1874	        }
1875	    }
