1877	    /// 用指定的长度风格拼一个 TLV；内容本身原样放入。
1878	    fn test_tlv(tag: u8, content: &[u8], style: LenStyle) -> Vec<u8> {
1879	        let mut out = vec![tag];
1880	        out.extend_from_slice(&test_len_bytes(content.len(), style));
1881	        out.extend_from_slice(content);
1882	        out
1883	    }
