1885	    /// 拼装一份 SPKI：算法参数缺省、位串未使用位数为零；三层 TLV 的长度
1886	    /// 字段风格可分别指定。OID 自身始终按规范短形式编码（这些用例里 OID
1887	    /// 内容都不超过 127 字节）。
1888	    fn styled_spki(
1889	        oid_content: &[u8],
1890	        key: &[u8],
1891	        outer_style: LenStyle,
1892	        alg_style: LenStyle,
1893	        bs_style: LenStyle,
1894	    ) -> Vec<u8> {
1895	        let oid = test_tlv(TAG_OID, oid_content, LenStyle::Canonical);
1896	        let algorithm = test_tlv(TAG_SEQUENCE, &oid, alg_style);
1897	        let mut bs_content = vec![0x00];
1898	        bs_content.extend_from_slice(key);
1899	        let bit_string = test_tlv(TAG_BIT_STRING, &bs_content, bs_style);
1900	        let mut outer_content = algorithm;
1901	        outer_content.extend_from_slice(&bit_string);
1902	        test_tlv(TAG_SEQUENCE, &outer_content, outer_style)
1903	    }
