1905	    /// 断言一份结构完整的容器被归类为“算法不支持”，且 OID 原样保留。
1906	    fn assert_unsupported_oid(der: &[u8], expected_arcs: &[u64]) {
1907	        let err = Ed25519PublicKey::from_spki_der(der).unwrap_err();
1908	        match &err {
1909	            ImportPublicKeyError::UnsupportedAlgorithm(oid) => {
1910	                assert_eq!(oid.arcs(), expected_arcs);
1911	                // 点分显示必须包含完整标识，包括末尾的段。
1912	                let dotted: String = expected_arcs
1913	                    .iter()
1914	                    .map(|arc| arc.to_string())
1915	                    .collect::<Vec<_>>()
1916	                    .join(".");
1917	                assert_eq!(oid.to_string(), dotted);
1918	                assert!(err.to_string().contains(&dotted));
1919	            }
1920	            other => panic!("expected UnsupportedAlgorithm({expected_arcs:?}), got {other:?}"),
1921	        }
1922	    }
