2332	    // ----- PEM（PUBLIC KEY）导入 -----
2333	    //
2334	    // PEM 入口只负责严格的外壳与严格 Base64 解码，还原出 DER 后完全
2335	    // 复用 from_spki_der。这一组测试覆盖：
2336	    // 1. PEM 与 DER 两个入口对同一把公钥完全等价（原始字节、按值比较、
2337	    //    十六进制显示含前导零）；
2338	    // 2. PEM 外壳的严格边界（标记、行结束、正文、块的数量）；
2339	    // 3. 标准 Base64 的严格解码（字母表、填充、未使用位）；
2340	    // 4. 还原出的 DER 截断/长度不符/多余字节 → Malformed；完整但算法
2341	    //    不同 → UnsupportedAlgorithm，OID 原样保留；DER 损坏时即使读到
2342	    //    其他算法标识也仍报 Malformed。
2343	
2344	    /// RFC 8410 示例 SPKI 的标准 Base64（独立依据：python3 base64 对
2345	    /// RFC8410_SPKI 的编码结果），60 个字符、末尾一个填充符。
2346	    const RFC8410_PEM_BODY: &str =
2347	        "MCowBQYDK2VwAyEA11qYAYKxCrfVS/7TyWQHOg7hcvPapiMlrwIaaPcHURo=";
2348	
2349	    /// 把若干正文行按给定行结束拼装成完整 PEM；`tail` 是尾标记后的字节。
2350	    fn pem_build(body_lines: &[&[u8]], eol: &[u8], tail: &[u8]) -> Vec<u8> {
2351	        let mut out = PEM_BEGIN.to_vec();
2352	        out.extend_from_slice(eol);
2353	        for line in body_lines {
2354	            out.extend_from_slice(line);
2355	            out.extend_from_slice(eol);
2356	        }
2357	        out.extend_from_slice(PEM_END);
2358	        out.extend_from_slice(tail);
2359	        out
2360	    }
2361	
2362	    /// 单行正文、LF、尾无换行。
2363	    fn pem_single_line(body: &[u8]) -> Vec<u8> {
2364	        pem_build(&[body], b"\n", b"")
2365	    }
