2367	    /// 用自定义首尾标签拼 PEM（LF、尾带一个 LF），专用于其他标签反例。
2368	    fn custom_label_pem(begin: &[u8], lines: &[&[u8]], end: &[u8]) -> Vec<u8> {
2369	        let mut out = begin.to_vec();
2370	        out.extend_from_slice(b"\n");
2371	        for line in lines {
2372	            out.extend_from_slice(line);
2373	            out.extend_from_slice(b"\n");
2374	        }
2375	        out.extend_from_slice(end);
2376	        out.push(b'\n');
2377	        out
2378	    }
