2380	    /// 最小标准 Base64 编码器（RFC 4648 标准字母表，带规范填充），只在
2381	    /// 测试里把已知 DER 包进 PEM 以构造输入；生产代码不含编码器。
2382	    fn b64encode_test(data: &[u8]) -> String {
2383	        const ALPHABET: &[u8; 64] =
2384	            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
2385	        let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
2386	        for chunk in data.chunks(3) {
2387	            let b0 = u32::from(chunk[0]);
2388	            let b1 = chunk.get(1).copied().map(u32::from);
2389	            let b2 = chunk.get(2).copied().map(u32::from);
2390	            let v = (b0 << 16) | (b1.unwrap_or(0) << 8) | b2.unwrap_or(0);
2391	            out.push(ALPHABET[((v >> 18) & 0x3f) as usize] as char);
2392	            out.push(ALPHABET[((v >> 12) & 0x3f) as usize] as char);
2393	            match (b1, b2) {
2394	                (Some(_), Some(_)) => {
2395	                    out.push(ALPHABET[((v >> 6) & 0x3f) as usize] as char);
2396	                    out.push(ALPHABET[(v & 0x3f) as usize] as char);
2397	                }
2398	                (Some(_), None) => {
2399	                    out.push(ALPHABET[((v >> 6) & 0x3f) as usize] as char);
2400	                    out.push('=');
2401	                }
2402	                _ => {
2403	                    out.push('=');
2404	                    out.push('=');
2405	                }
2406	            }
2407	        }
2408	        out
2409	    }
