2411	    /// 按 DER 字节生成完整 PEM：单行正文、行间 LF、尾标记后无换行。
2412	    fn pem_of_der(der: &[u8]) -> Vec<u8> {
2413	        pem_single_line(b64encode_test(der).as_bytes())
2414	    }
